118→      emailRule: value => /.+@.+\..+/.test(value) || 'Correo electrónico inválido',
119→      isValid: false,
120→      countries: [],
121→      selectedCountry: null,
122→    };
123→  },
124→  created() {
125→    this.getCountries();
126→  },
127→  methods: {
128→
129→    async getDocumentTemplate (selectedValue) {
130→      // Usar allFields (todos los PDFs) si está disponible, sino fallback a fields
131→      const sourceFields = this.allFields && this.allFields.length > 0 ? this.allFields : this.fields;
132→      const signersFieldsArray = Array.isArray(sourceFields) ? sourceFields : [sourceFields];
133→
134→      const selectedType = selectedValue.id;
135→
136→      const response =  await this.$axios({
137→          buildURL: {
138→              key: "admin.signatureRequest.downloadPdfTemplate",
139→          },
140→          data : {
141→              documentHeaderId: selectedType,
142→              signers_fields: signersFieldsArray,
143→              countryId: this.selectedCountry || 1
144→          },
145→          responseType: 'blob',
146→      });
147→
148→      if (!response) return;
149→
150→      const blobUrl = window.URL.createObjectURL(response);
151→
152→      const a = document.createElement('a');
153→      a.href = blobUrl;
154→      a.download = `Plantilla del grupo ${selectedValue.name}_${moment().format('DD-MM-YYYY h-m-s')}`;
155→      a.style.display = 'none';
156→
157→      document.body.appendChild(a);
158→      a.click();
159→
160→      window.URL.revokeObjectURL(blobUrl);
161→      document.body.removeChild(a);    
162→    },
163→
164→    submitForm() {
165→      if (this.$refs.submitForm.validate()) {
166→        this.$emit('submit-form', { excel_file: this.excel_file, fields: this.fields, countryId: this.selectedCountry || 1 });
167→      }
168→    },
169→    async getCountries () {
170→        try {
171→
172→            const response = await this.$axios({
173→                method: 'GET',
174→                url: '/get_countries',
175→            }); 
176→
177→            this.countries = response.data;
178→            this.selectedCountry = this.$state.auth_user.data.company_country_id || 1; 
179→
180→        } catch (error) {
181→            console.error(error);
182→        }
183→    },
184→  },
185→};
