 253→async function exportDocumentsPackagesPdf(req, res) {
 254→    try {
 255→
 256→        const countryId = req.body.countryId;
 257→
 258→        const signers_fields = req.body.signers_fields;
 259→
 260→        const documentTypes = await db.identification_types.findMany({
 261→            where: {
 262→                country_id: parseInt(countryId),
 263→            },
 264→            select: {
 265→                id: true,
 266→                name: true,
 267→                field_type: true,
 268→            }
 269→        });
 270→
 271→        // Separar campos de firma de variables
 272→        const signatureFields = signers_fields.filter(field => field.type === 'signature' || (field.name && field.name.includes('FIRMA')));
 273→        const variableFields = signers_fields.filter(field => field.type === 'variable');
 274→
 275→        // Deduplicar firmantes por nombre
 276→        const signers_names = [...new Set(signatureFields.map(field => {
 277→            return field.name.replace(/\[\$|\]/g, '');
 278→        }))];
 279→
 280→        const workbook = new ExcelJS.Workbook();
 281→        const worksheet = workbook.addWorksheet('Cargue Masivo');       
 282→
 283→        const columns = [
 284→            { header: 'Fecha límite para realizar la firma', key: 'expires_in_days', width: 30 },
 285→            { header: 'Número de contrato', key: 'contract_number', width: 20 },
 286→        ];
 287→
 288→        const doctypeColumnKeys = [];
 289→        const documentColumnKeys = [];
 290→        const phoneColumnKeys = [];
 291→        const emailColumnKeys = [];
 292→
 293→        signers_names.forEach((field, index) => {
 294→
 295→            const match = field.match(/FIRMA(\d+)/);
 296→            const signerNumber = match ? match[1] : '';
 297→
 298→            columns.push({ header: `Firmante${signerNumber}_Nombre`, key: `signer${signerNumber}_name`, width: 15 });
 299→            columns.push({ header: `Firmante${signerNumber}_Apellido`, key: `signer${signerNumber}_surname`, width: 15 });
 300→            const emailKey = `signer${signerNumber}_email`;
 301→            columns.push({ header: `Firmante${signerNumber}_Correo`, key: emailKey, width: 30 });
 302→            emailColumnKeys.push(emailKey);
 303→                        
 304→            const phoneKey = `signer${signerNumber}_phone`;
 305→            columns.push({ header: `Firmante${signerNumber}_Celular`, key: phoneKey, width: 20 });
 306→            phoneColumnKeys.push(phoneKey);
 307→
 308→            const doctypeKey = `signer${signerNumber}_doctype`;
 309→            columns.push({ header: `Firmante${signerNumber}_Tipo_documento`, key: doctypeKey, width: 30 });
 310→            doctypeColumnKeys.push(doctypeKey);
 311→
 312→            const documentKey = `signer${signerNumber}_document`;
 313→            columns.push({ header: `Firmante${signerNumber}_Documento`, key: documentKey, width: 20 });
 314→            documentColumnKeys.push(documentKey);
 315→        });
 316→
 317→        // Agregar columnas para variables (deduplicar por nombre)
