##### 3.4 Add Mapping Handler Methods

```javascript
async loadMappingConfig() {
    try {
        const response = await this.$axios({
            buildURL: {
                key: 'admin.signatureRequest.getMappingConfig',
                params: {
                    documentPackageHeaderId: this.document.id,
                },
            },
        });
        if (response && response.status === true && response.data) {
            this.savedMappingConfig = response.data;
        }
    } catch (e) {
        console.error('Error loading mapping config:', e);
    }
},

onMappingConfirmed({ mappings, resolvedVariableValues }) {
    this.mappingDialogVisible = false;

    // Re-key variableValues in importResponseData based on confirmed mapping
    // The mapping tells us: excelHeader VAR_X -> pdfVariable [$Y]
    // Currently variableValues has keys matching excel headers (without VAR_ prefix)
    // We need to re-key so they match PDF field names (without [$...])

    const mappingLookup = {};
    mappings.forEach(m => {
        if (m.pdfVariable) {
            const excelVarName = m.excelHeader.replace('VAR_', '');
            const pdfVarName = m.pdfVariable.replace(/\[\$|\]/g, '');
            mappingLookup[excelVarName] = pdfVarName;
        }
    });

    // Re-key variable values in each record
    this.importResponseData = this.importResponseData.map(record => {
        const newVariableValues = {};
        for (const [excelKey, value] of Object.entries(record.variableValues || {})) {
            const pdfKey = mappingLookup[excelKey] || excelKey;
            newVariableValues[pdfKey] = value;
        }
        return { ...record, variableValues: newVariableValues };
    });

    // Now proceed to records table
    this.fillTable(this.importResponseData, this.importDocumentHeaderId);
},

async onSaveMappingConfig(config) {
    try {
        await this.$axios({
            buildURL: {
                key: 'admin.signatureRequest.saveMappingConfig',
            },
            data: {
                documentPackageHeaderId: this.document.id,
                mappingConfig: config,
            },
        });
        this.showToast('Configuracion de mapeo guardada', 'success');
    } catch (e) {
        console.error('Error saving mapping config:', e);
        this.showToast('Error al guardar la configuracion de mapeo');
    }
},
```

